mapper.select:
SELECT a.finprod_id id, a.finprod_type2 text,a.FINPROD_ABBR parentId, 'FINPROD_TYPE_TG' as col FROM FIN_PRODUCT a WHERE a.finprod_type2 in ('F01', 'F10','F06')
AND a.finprod_id = #{finprodId,jdbcType=VARCHAR}
AND a.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
AND a.TRADE_MARKET in (#{TRADE_PLACE_03}, #{TRADE_PLACE_04}) order by id asc

select finprod_Id finprodId, OTH_TYPE othCodeType, oth_Code othCode from FIN_PRODUCT_OTH_CODE where 1=1
and finprod_Id = #{finprodId,jdbcType=VARCHAR}
and OTH_TYPE = #{othCodeType,jdbcType=VARCHAR}
